CREATE TRIGGER ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision OR ((NEW.namespace IS NOT OLD.namespace OR NEW.operation_key IS NOT OLD.operation_key) AND NOT (NEW.namespace='' AND NEW.operation_key='' AND NOT EXISTS(SELECT 1 FROM ik_d1_streams WHERE id=OLD.stream_id) AND EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=OLD.stream_id AND kind='stream'))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;

-- Upstream source: default-seed/migrations/core/0020_import_erasure_append_only.sql
-- A store that applied 0018 before these triggers joined import-kit's
-- d1RetirementAppendOnly: an insert over an existing erasure journal or
-- retirement row (INSERT OR REPLACE included) is refused.
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_insert BEFORE INSERT ON ik_d1_erasure_journal WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_journal WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_insert BEFORE INSERT ON ik_d1_retirements WHEN EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=NEW.id AND kind=NEW.kind) BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;

-- Upstream source: default-seed/migrations/core/0021_import_preparation_steps.sql
-- import-kit d1PreparationStepsSchema: control rows for preparations made across
-- requests (prepareD1ImportSteps). Erasure, cancellation and header retirement read it.
CREATE TABLE IF NOT EXISTS ik_d1_preparation_steps (id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL, mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, operation_key TEXT NOT NULL, reversal_policy TEXT NOT NULL, codec_id TEXT, source_digest TEXT NOT NULL, total INTEGER NOT NULL, records INTEGER NOT NULL DEFAULT 0, stages TEXT NOT NULL DEFAULT '[]', phase TEXT NOT NULL CHECK(phase IN ('collecting','hashing','combining','prepared')), hash_json TEXT, fingerprint TEXT, verified_revision INTEGER, revision INTEGER NOT NULL DEFAULT 0, UNIQUE(destination,principal_id,operation_key));

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_binding BEFORE UPDATE OF id,destination,namespace,mapping_version,principal_id,operation_key,reversal_policy,codec_id,source_digest,total ON ik_d1_preparation_steps BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_BINDING_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_revision BEFORE UPDATE ON ik_d1_preparation_steps WHEN NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_CHANGED'); END;

-- Upstream source: default-seed/migrations/core/0022_import_stream_sources.sql
-- import-kit d1PreparationStepsSchema addition: a stream published by
-- prepareD1ImportSteps keeps the source digest its steps began with, so only
-- that same upload replays as published under its operation key.
CREATE TABLE IF NOT EXISTS ik_d1_stream_sources (stream_id TEXT PRIMARY KEY REFERENCES ik_d1_streams(id) ON DELETE CASCADE, destination TEXT NOT NULL, source_digest TEXT NOT NULL);

-- PORT-001. Every money record stores its ISO 4217 currency. Rows recorded before
-- this migration were entered while Terrace labelled money A$ (AUD): they keep
-- AUD and are never relabelled or converted. New tenancies are USD.
ALTER TABLE tt_tenancies ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
-- The property's IANA time zone. Earlier rows were dated as UTC days and keep
-- UTC until a manager sets the property's zone.
ALTER TABLE tt_tenancies ADD COLUMN time_zone TEXT NOT NULL DEFAULT 'UTC';
ALTER TABLE tt_charges ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE tt_receipts ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE tt_adjustments ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE tt_lease_history ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE tt_maintenance_jobs ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
-- A record's currency never changes, and a child record carries its parent's.
CREATE TRIGGER tt_tenancy_currency_fixed BEFORE UPDATE OF currency ON tt_tenancies WHEN NEW.currency IS NOT OLD.currency
BEGIN SELECT RAISE(ABORT,'Currency is never relabelled'); END;
CREATE TRIGGER tt_charge_currency_fixed BEFORE UPDATE OF currency ON tt_charges WHEN NEW.currency IS NOT OLD.currency
BEGIN SELECT RAISE(ABORT,'Currency is never relabelled'); END;
CREATE TRIGGER tt_charge_currency BEFORE INSERT ON tt_charges WHEN EXISTS(SELECT 1 FROM tt_tenancies WHERE id=NEW.tenancy_id AND currency IS NOT NEW.currency)
BEGIN SELECT RAISE(ABORT,'Charge currency must match its tenancy'); END;
CREATE TRIGGER tt_receipt_currency BEFORE INSERT ON tt_receipts WHEN EXISTS(SELECT 1 FROM tt_charges WHERE id=NEW.charge_id AND currency IS NOT NEW.currency)
BEGIN SELECT RAISE(ABORT,'Receipt currency must match its charge'); END;
CREATE TRIGGER tt_adjustment_currency BEFORE INSERT ON tt_adjustments WHEN EXISTS(SELECT 1 FROM tt_charges WHERE id=NEW.charge_id AND currency IS NOT NEW.currency)
BEGIN SELECT RAISE(ABORT,'Adjustment currency must match its charge'); END;
CREATE TRIGGER tt_job_currency BEFORE INSERT ON tt_maintenance_jobs WHEN EXISTS(SELECT 1 FROM tt_tenancies WHERE id=NEW.tenancy_id AND currency IS NOT NEW.currency)
BEGIN SELECT RAISE(ABORT,'Estimate currency must match its tenancy'); END;
-- The US management company (one per installation), its legal entities and
-- their USD operating accounts. An EIN is a format-checked reference; an
-- account is a recorded reference (no full account or routing number).
CREATE TABLE tt_company (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), name TEXT NOT NULL,
 country TEXT NOT NULL CHECK(country='US'), currency TEXT NOT NULL CHECK(currency='USD'), time_zone TEXT NOT NULL,
 office_email TEXT NOT NULL, office_phone TEXT NOT NULL, office_address TEXT NOT NULL,
 version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE tt_entities (
 id TEXT PRIMARY KEY, legal_name TEXT NOT NULL, ein TEXT NOT NULL UNIQUE CHECK(ein GLOB '[0-9][0-9]-[0-9][0-9][0-9][0-9][0-9][0-9][0-9]'),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE tt_operating_accounts (
 id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES tt_entities(id), name TEXT NOT NULL, bank_name TEXT NOT NULL,
 last4 TEXT NOT NULL CHECK(last4 GLOB '[0-9][0-9][0-9][0-9]'), currency TEXT NOT NULL CHECK(currency='USD'),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(entity_id,name)
);

-- WORK-004: the vendor directory, the qualification each maintenance assignment met or missed, and the
-- documented human exceptions that let held work proceed.
CREATE TABLE tt_vendors (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL,
 specialties TEXT NOT NULL, service_areas TEXT NOT NULL,
 w9 TEXT NOT NULL CHECK(w9 IN ('received','missing')), insurance_expires TEXT NOT NULL,
 license_number TEXT, license_expires TEXT, availability TEXT NOT NULL,
 rate_cents INTEGER CHECK(rate_cents IS NULL OR rate_cents>0), currency TEXT NOT NULL CHECK(currency='USD'),
 standing TEXT NOT NULL CHECK(standing IN ('preferred','approved','blocked')),
 version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL,
 CHECK((license_number IS NULL) = (license_expires IS NULL))
);
-- Jobs prepared before WORK-004 keep vendor_id, trade and qualification NULL (an unlisted vendor).
ALTER TABLE tt_maintenance_jobs ADD COLUMN vendor_id TEXT REFERENCES tt_vendors(id) ON DELETE SET NULL;
ALTER TABLE tt_maintenance_jobs ADD COLUMN trade TEXT;
ALTER TABLE tt_maintenance_jobs ADD COLUMN qualification TEXT;
CREATE TABLE tt_vendor_assignments (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE,
 vendor_id TEXT, trade_name TEXT NOT NULL, trade TEXT, issues TEXT NOT NULL, assigned_by TEXT NOT NULL, assigned_at TEXT NOT NULL
);
CREATE INDEX tt_vendor_assignment_job ON tt_vendor_assignments(job_id,assigned_at);
CREATE TABLE tt_vendor_exceptions (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE,
 vendor_id TEXT, issues TEXT NOT NULL, reason TEXT NOT NULL,
 approved_by TEXT NOT NULL, approved_role TEXT NOT NULL CHECK(approved_role IN ('owner','admin')), approved_at TEXT NOT NULL
);
CREATE INDEX tt_vendor_exception_job ON tt_vendor_exceptions(job_id);
CREATE TRIGGER tt_vendor_exception_immutable BEFORE UPDATE ON tt_vendor_exceptions
BEGIN SELECT RAISE(ABORT,'A qualification exception is never edited'); END;

-- WORK-010: recurring maintenance schedules, their dated occurrences and the one order each occurrence gets.
CREATE TABLE tt_schedules (
 id TEXT PRIMARY KEY, tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id) ON DELETE CASCADE,
 title TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('asset','seasonal','inspection')),
 asset_id TEXT REFERENCES tt_assets(id) ON DELETE SET NULL, inspection_id TEXT REFERENCES tt_inspections(id) ON DELETE SET NULL,
 trade TEXT NOT NULL, vendor_id TEXT NOT NULL REFERENCES tt_vendors(id),
 interval_months INTEGER NOT NULL CHECK(interval_months BETWEEN 1 AND 60), first_due TEXT NOT NULL,
 lead_days INTEGER NOT NULL CHECK(lead_days BETWEEN 0 AND 90),
 budget_cents INTEGER NOT NULL CHECK(budget_cents>0), currency TEXT NOT NULL CHECK(currency IN ('USD','AUD')),
 version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE tt_schedule_occurrences (
 id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL REFERENCES tt_schedules(id) ON DELETE CASCADE,
 due_date TEXT NOT NULL, deferred_to TEXT, defer_reason TEXT, deferred_by TEXT, asset_id TEXT,
 created_at TEXT NOT NULL, UNIQUE(schedule_id,due_date),
 CHECK((deferred_to IS NULL) = (defer_reason IS NULL))
);
ALTER TABLE tt_maintenance_jobs ADD COLUMN occurrence_id TEXT REFERENCES tt_schedule_occurrences(id) ON DELETE SET NULL;
-- At most one order per occurrence, however often the scheduler runs.
CREATE UNIQUE INDEX tt_job_occurrence ON tt_maintenance_jobs(occurrence_id) WHERE occurrence_id IS NOT NULL;
-- When an asset is replaced, its schedules follow the replacement.
CREATE TRIGGER tt_schedule_follows_asset AFTER UPDATE OF replaced_by ON tt_assets WHEN NEW.replaced_by IS NOT NULL
BEGIN UPDATE tt_schedules SET asset_id=NEW.replaced_by,version=version+1 WHERE asset_id=NEW.id; END;

-- PAY-001: effective lease charge terms and the charges and concession reductions a run posts from them.
CREATE TABLE tt_lease_terms (
 id TEXT PRIMARY KEY, tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK(kind IN ('rent','utility','pet','parking','concession')), description TEXT NOT NULL,
