 starts TEXT NOT NULL, ends TEXT, replaces TEXT, version INTEGER NOT NULL DEFAULT 1,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, CHECK(ends IS NULL OR ends >= starts)
);
CREATE INDEX tt_lease_term_tenancy ON tt_lease_terms(tenancy_id,kind,starts);
-- A posted charge names the term and period it came from; its reference is unique per tenancy.
ALTER TABLE tt_charges ADD COLUMN term_id TEXT;
ALTER TABLE tt_charges ADD COLUMN period_start TEXT;
ALTER TABLE tt_charges ADD COLUMN period_end TEXT;
-- A concession posts as a reduction with a reference, at most once per charge.
ALTER TABLE tt_adjustments ADD COLUMN reference TEXT;
CREATE UNIQUE INDEX tt_adjustment_reference ON tt_adjustments(charge_id,reference) WHERE reference IS NOT NULL;

-- PORT-002: portfolios, properties (buildings) and units, independent of tenancies. A tenancy may sit on a unit;
-- tenancies recorded before this rule keep only their address.
CREATE TABLE tt_portfolios (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE tt_properties (
 id TEXT PRIMARY KEY, portfolio_id TEXT NOT NULL REFERENCES tt_portfolios(id), name TEXT NOT NULL, address TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('single_family','duplex','multifamily','townhouse','condo')), time_zone TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(portfolio_id,name)
);
CREATE TABLE tt_units (
 id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES tt_properties(id), identifier TEXT NOT NULL,
 bedrooms INTEGER NOT NULL CHECK(bedrooms BETWEEN 0 AND 20), bathrooms REAL NOT NULL CHECK(bathrooms BETWEEN 0 AND 20),
 amenities TEXT NOT NULL, rentable INTEGER NOT NULL CHECK(rentable IN (0,1)),
 version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,identifier)
);
ALTER TABLE tt_tenancies ADD COLUMN unit_id TEXT REFERENCES tt_units(id);
-- A lease ended before its end date keeps that end date; ended_on is the move-out day.
ALTER TABLE tt_tenancies ADD COLUMN ended_on TEXT;
ALTER TABLE tt_tenancies ADD COLUMN end_reason TEXT;
ALTER TABLE tt_tenancies ADD COLUMN transferred_from TEXT;
CREATE INDEX tt_tenancy_unit ON tt_tenancies(unit_id,start_date);
-- Equipment recorded on a unit's tenancy is also the unit's (WORK-002).
ALTER TABLE tt_assets ADD COLUMN unit_id TEXT REFERENCES tt_units(id);

-- WORK-013: a make-ready board per vacated unit: dependent tasks, the planned ready date and the published
-- available date, which needs every task checked by an owner or admin.
CREATE TABLE tt_turnovers (
 id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES tt_units(id), move_out TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','ready')), available_on TEXT,
 published_by TEXT, published_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 CHECK((state='ready') = (available_on IS NOT NULL AND published_by IS NOT NULL))
);
CREATE UNIQUE INDEX tt_turnover_open ON tt_turnovers(unit_id) WHERE state='open';
CREATE TABLE tt_turnover_tasks (
 id TEXT PRIMARY KEY, turnover_id TEXT NOT NULL REFERENCES tt_turnovers(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK(kind IN ('inspection','deposit','repair','cleaning','utility','listing')),
 title TEXT NOT NULL, assignee TEXT NOT NULL, duration_days INTEGER NOT NULL CHECK(duration_days BETWEEN 1 AND 60),
 delay_days INTEGER NOT NULL DEFAULT 0 CHECK(delay_days BETWEEN 0 AND 120), quote_cents INTEGER CHECK(quote_cents IS NULL OR quote_cents>0),
 depends_on TEXT NOT NULL, position INTEGER NOT NULL,
 state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','submitted','checked')),
 submitted_by TEXT, submitted_at TEXT, checked_by TEXT, checked_at TEXT, version INTEGER NOT NULL DEFAULT 1
);
ALTER TABLE tt_units ADD COLUMN available_on TEXT;

-- REPORT-001: a unit's market rent, and the method of a recorded external receipt. Receipts recorded before
-- this rule keep no method and are reported as "method not recorded".
ALTER TABLE tt_units ADD COLUMN market_rent_cents INTEGER CHECK(market_rent_cents IS NULL OR market_rent_cents>0);
ALTER TABLE tt_receipts ADD COLUMN method TEXT CHECK(method IS NULL OR method IN ('ach','card','cash','check','other'));

-- PORT-001 legacy currency. Terrace relabelled A$ as $ before it stored a currency
-- (commit 1d87bf4), so a tenancy that 0018 marked AUD may hold USD entered under
-- the $ label: its currency is unconfirmed. An imported tenancy that names its
-- time zone came from a PORT-001 CSV whose currency was explicit, so it stays
-- confirmed; a transfer follows the lease it came from.
ALTER TABLE tt_tenancies ADD COLUMN currency_confirmed INTEGER NOT NULL DEFAULT 1 CHECK(currency_confirmed IN (0,1));
UPDATE tt_tenancies SET currency_confirmed=0 WHERE currency='AUD' AND transferred_from IS NULL AND (import_revision IS NULL OR time_zone='UTC');
UPDATE tt_tenancies SET currency_confirmed=0 WHERE currency='AUD' AND id IN (WITH RECURSIVE chain(id) AS (SELECT id FROM tt_tenancies WHERE currency_confirmed=0 UNION SELECT t.id FROM tt_tenancies t JOIN chain ON t.transferred_from=chain.id) SELECT id FROM chain);
-- The owner confirms the label once per installation; no amount is converted.
CREATE TABLE tt_currency_confirmation (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), currency TEXT NOT NULL CHECK(currency IN ('USD','AUD')),
 tenancies INTEGER NOT NULL, confirmed_by TEXT NOT NULL, confirmed_at TEXT NOT NULL
);
-- A confirmed record's currency never changes; an unconfirmed one changes only with the owner's confirmation.
DROP TRIGGER tt_tenancy_currency_fixed;
CREATE TRIGGER tt_tenancy_currency_fixed BEFORE UPDATE OF currency ON tt_tenancies WHEN NEW.currency IS NOT OLD.currency AND OLD.currency_confirmed=1
BEGIN SELECT RAISE(ABORT,'Currency is never relabelled'); END;
CREATE TRIGGER tt_tenancy_confirmed_fixed BEFORE UPDATE OF currency_confirmed ON tt_tenancies WHEN OLD.currency_confirmed=1 AND NEW.currency_confirmed IS NOT 1
BEGIN SELECT RAISE(ABORT,'A confirmed currency stays confirmed'); END;
DROP TRIGGER tt_charge_currency_fixed;
CREATE TRIGGER tt_charge_currency_fixed BEFORE UPDATE OF currency ON tt_charges WHEN NEW.currency IS NOT OLD.currency AND NOT EXISTS(SELECT 1 FROM tt_tenancies WHERE id=OLD.tenancy_id AND currency_confirmed=0)
BEGIN SELECT RAISE(ABORT,'Currency is never relabelled'); END;

-- WORK-003. Comparable vendor quotes per job; the owner's per-job spending limit and annual maintenance
-- budget, recorded per property (per tenancy when it has no unit record); the owner's decision on work above
-- them, recorded by staff for the owner; and one approval per approved job version, because a change to
-- scope, vendor or price reopens authorization.
CREATE TABLE tt_job_quotes (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE,
 vendor_id TEXT, vendor_name TEXT NOT NULL, vendor_email TEXT NOT NULL, scope TEXT NOT NULL, available_date TEXT NOT NULL,
 amount_cents INTEGER NOT NULL CHECK(amount_cents>0), tax_cents INTEGER NOT NULL CHECK(tax_cents>=0), currency TEXT NOT NULL,
 recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE INDEX tt_job_quotes_job ON tt_job_quotes(job_id);
CREATE TABLE tt_work_limits (
 scope TEXT PRIMARY KEY, limit_cents INTEGER NOT NULL CHECK(limit_cents>0), budget_cents INTEGER CHECK(budget_cents IS NULL OR budget_cents>0),
 currency TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, set_by TEXT NOT NULL, set_at TEXT NOT NULL
);
CREATE TABLE tt_owner_decisions (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE, job_version INTEGER NOT NULL,
 terms_sha256 TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('approved','declined')),
 source TEXT NOT NULL CHECK(source IN ('email','document','call')), reference TEXT NOT NULL,
 recorded_by TEXT NOT NULL, recorded_role TEXT NOT NULL CHECK(recorded_role IN ('owner','admin')), recorded_at TEXT NOT NULL,
 UNIQUE(job_id,job_version)
);
CREATE TRIGGER tt_owner_decision_immutable BEFORE UPDATE ON tt_owner_decisions
BEGIN SELECT RAISE(ABORT,'An owner decision is never edited'); END;
ALTER TABLE tt_maintenance_jobs ADD COLUMN scope TEXT;
ALTER TABLE tt_maintenance_jobs ADD COLUMN quote_id TEXT;
CREATE TABLE tt_maintenance_approvals_next (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE,
 job_version INTEGER NOT NULL, snapshot TEXT NOT NULL, sha256 TEXT NOT NULL,
 approved_by TEXT NOT NULL, approved_role TEXT NOT NULL CHECK(approved_role IN ('owner','admin')),
 approved_at TEXT NOT NULL, UNIQUE(job_id,job_version)
);
INSERT INTO tt_maintenance_approvals_next SELECT id,job_id,job_version,snapshot,sha256,approved_by,approved_role,approved_at FROM tt_maintenance_approvals;
DROP TABLE tt_maintenance_approvals;
ALTER TABLE tt_maintenance_approvals_next RENAME TO tt_maintenance_approvals;
CREATE TRIGGER tt_maintenance_approval_immutable BEFORE UPDATE ON tt_maintenance_approvals
BEGIN SELECT RAISE(ABORT,'Maintenance approval is immutable'); END;

-- WORK-008. A vendor's completion report on handed-off work (recorded by staff: there is no vendor portal yet),
-- the resident's answer to "is the original issue resolved?" for each report (recorded by staff: Terrace does
-- not contact residents yet), and closure without the resident's confirmation. Every row is append-only.
ALTER TABLE tt_maintenance_jobs ADD COLUMN resolution TEXT CHECK(resolution IS NULL OR resolution IN ('awaiting_check','reopened','resolved','closed'));
CREATE TABLE tt_completion_attempts (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE, attempt INTEGER NOT NULL CHECK(attempt>0),
 completed_date TEXT NOT NULL, summary TEXT NOT NULL, reference TEXT NOT NULL,
 callback TEXT CHECK((attempt=1 AND callback IS NULL) OR (attempt>1 AND callback IN ('warranty','billable'))),
 recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL, UNIQUE(job_id,attempt)
);
CREATE TABLE tt_resident_checks (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE,
 attempt_id TEXT NOT NULL REFERENCES tt_completion_attempts(id) ON DELETE CASCADE,
 outcome TEXT NOT NULL CHECK(outcome IN ('confirmed','unresolved','no_response')), note TEXT NOT NULL,
 satisfaction INTEGER CHECK(satisfaction IS NULL OR (outcome='confirmed' AND satisfaction BETWEEN 1 AND 5)),
 safety_concern TEXT, label TEXT NOT NULL, recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE TABLE tt_job_closures (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES tt_maintenance_jobs(id) ON DELETE CASCADE, reason TEXT NOT NULL,
 closed_by TEXT NOT NULL, closed_role TEXT NOT NULL CHECK(closed_role IN ('owner','admin')), closed_at TEXT NOT NULL
);
CREATE TRIGGER tt_completion_attempt_immutable BEFORE UPDATE ON tt_completion_attempts BEGIN SELECT RAISE(ABORT,'A completion report is never edited'); END;
CREATE TRIGGER tt_resident_check_immutable BEFORE UPDATE ON tt_resident_checks BEGIN SELECT RAISE(ABORT,'A resident check is never edited'); END;
CREATE TRIGGER tt_job_closure_immutable BEFORE UPDATE ON tt_job_closures BEGIN SELECT RAISE(ABORT,'A closure is never edited'); END;

-- PORT-003. Property owners (individuals or entities) apart from a tenancy's recorded owner contact, their W-9
-- collection status as staff record it (no TIN is stored), dated ownership share sets per property, and dated
-- management agreements with the fee percent and reserve requirement. Share sets and agreements are never edited:
-- a transfer or a new agreement is a new dated row.
CREATE TABLE tt_owners (
 id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('individual','entity')), legal_name TEXT NOT NULL, email TEXT NOT NULL,
 mailing_address TEXT NOT NULL,
 w9_status TEXT NOT NULL DEFAULT 'not_requested' CHECK(w9_status IN ('not_requested','requested','received')), w9_date TEXT, w9_location TEXT,
 version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(legal_name,email)
);
CREATE TABLE tt_w9_events (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES tt_owners(id), status TEXT NOT NULL CHECK(status IN ('requested','received')),
 on_date TEXT NOT NULL, location TEXT, recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE TABLE tt_ownership_sets (
 id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES tt_properties(id), effective_from TEXT NOT NULL, reason TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,effective_from)
);
CREATE TABLE tt_ownership_shares (
 set_id TEXT NOT NULL REFERENCES tt_ownership_sets(id), owner_id TEXT NOT NULL REFERENCES tt_owners(id),
 share_bp INTEGER NOT NULL CHECK(share_bp BETWEEN 1 AND 10000), position INTEGER NOT NULL, PRIMARY KEY(set_id,owner_id)
);
CREATE TABLE tt_management_agreements (
 id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES tt_properties(id), starts TEXT NOT NULL,
 fee_bp INTEGER NOT NULL CHECK(fee_bp BETWEEN 0 AND 10000), reserve_cents INTEGER NOT NULL CHECK(reserve_cents>=0), reference TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,starts)
);
CREATE TRIGGER tt_w9_event_immutable BEFORE UPDATE ON tt_w9_events BEGIN SELECT RAISE(ABORT,'A W-9 record is never edited'); END;
CREATE TRIGGER tt_ownership_set_immutable BEFORE UPDATE ON tt_ownership_sets BEGIN SELECT RAISE(ABORT,'Ownership history is never edited'); END;
CREATE TRIGGER tt_ownership_share_immutable BEFORE UPDATE ON tt_ownership_shares BEGIN SELECT RAISE(ABORT,'Ownership history is never edited'); END;
CREATE TRIGGER tt_agreement_immutable BEFORE UPDATE ON tt_management_agreements BEGIN SELECT RAISE(ABORT,'An agreement is never edited'); END;
INSERT INTO tt_role_actions(role,action) VALUES
('portfolio_manager','owner.add'),('portfolio_manager','owner.w9'),('portfolio_manager','ownership.set'),('portfolio_manager','agreement.set');

-- ROLE-003. Dual control: who prepared a maintenance job's current terms (a revision, quote selection or
-- reassignment makes that person a preparer too), the label kept when the only person who could approve is the
-- one who prepared, and the owner's quote requirement (how many quotes above which estimate) beside the limits.
ALTER TABLE tt_maintenance_jobs ADD COLUMN revised_by TEXT;
ALTER TABLE tt_maintenance_approvals ADD COLUMN approval_label TEXT;
ALTER TABLE tt_proposals ADD COLUMN approval_label TEXT;
ALTER TABLE tt_work_limits ADD COLUMN quotes_needed INTEGER CHECK(quotes_needed IS NULL OR quotes_needed BETWEEN 2 AND 10);
ALTER TABLE tt_work_limits ADD COLUMN quotes_above_cents INTEGER CHECK(quotes_above_cents IS NULL OR quotes_above_cents>=0);

-- SAFE-002. Attributable, immutable operating history. Each history row keeps the actor's role and role version
-- at the time (the policy they acted under), the tenancy it concerns, the source the person gave (a lease reference,
-- receipt or handoff reference, or reason) and its outcome; sensitive reads and exports are rows too. History,
-- charges, receipts and corrections are never edited; a charge, receipt or correction is deleted only with its
-- tenancy (owner erasure or a move-in undo), and history rows never.
ALTER TABLE tt_audit ADD COLUMN role TEXT;
ALTER TABLE tt_audit ADD COLUMN policy TEXT;
ALTER TABLE tt_audit ADD COLUMN tenancy_id TEXT;
ALTER TABLE tt_audit ADD COLUMN source TEXT;
ALTER TABLE tt_audit ADD COLUMN outcome TEXT;
CREATE INDEX tt_audit_at ON tt_audit(at);
CREATE TRIGGER tt_audit_immutable BEFORE UPDATE ON tt_audit BEGIN SELECT RAISE(ABORT,'History is never edited'); END;
CREATE TRIGGER tt_audit_kept BEFORE DELETE ON tt_audit BEGIN SELECT RAISE(ABORT,'History is never deleted'); END;
-- The one change allowed is PORT-001's one-time relabel of an unconfirmed tenancy's money from AUD to USD (no amount changes).
CREATE TRIGGER tt_charge_immutable BEFORE UPDATE OF id,tenancy_id,due_date,amount_cents,description,reference,created_at,term_id,period_start,period_end ON tt_charges BEGIN SELECT RAISE(ABORT,'Accounting history is never edited'); END;
CREATE TRIGGER tt_receipt_immutable BEFORE UPDATE OF id,charge_id,amount_cents,received_date,reference,created_at,method ON tt_receipts BEGIN SELECT RAISE(ABORT,'Accounting history is never edited'); END;
CREATE TRIGGER tt_adjustment_immutable BEFORE UPDATE OF id,charge_id,amount_cents,reason,at,reference ON tt_adjustments BEGIN SELECT RAISE(ABORT,'Accounting history is never edited'); END;
CREATE TRIGGER tt_charge_relabel BEFORE UPDATE OF currency ON tt_charges WHEN NOT (OLD.currency='AUD' AND NEW.currency='USD' AND EXISTS(SELECT 1 FROM tt_tenancies WHERE id=OLD.tenancy_id AND currency_confirmed=0)) BEGIN SELECT RAISE(ABORT,'Accounting history is never edited'); END;
CREATE TRIGGER tt_receipt_relabel BEFORE UPDATE OF currency ON tt_receipts WHEN NOT (OLD.currency='AUD' AND NEW.currency='USD' AND EXISTS(SELECT 1 FROM tt_charges q JOIN tt_tenancies t ON t.id=q.tenancy_id WHERE q.id=OLD.charge_id AND t.currency_confirmed=0)) BEGIN SELECT RAISE(ABORT,'Accounting history is never edited'); END;
CREATE TRIGGER tt_adjustment_relabel BEFORE UPDATE OF currency ON tt_adjustments WHEN NOT (OLD.currency='AUD' AND NEW.currency='USD' AND EXISTS(SELECT 1 FROM tt_charges q JOIN tt_tenancies t ON t.id=q.tenancy_id WHERE q.id=OLD.charge_id AND t.currency_confirmed=0)) BEGIN SELECT RAISE(ABORT,'Accounting history is never edited'); END;
CREATE TRIGGER tt_charge_kept BEFORE DELETE ON tt_charges WHEN EXISTS(SELECT 1 FROM tt_tenancies WHERE id=OLD.tenancy_id) BEGIN SELECT RAISE(ABORT,'Accounting history is never deleted'); END;
CREATE TRIGGER tt_receipt_kept BEFORE DELETE ON tt_receipts WHEN EXISTS(SELECT 1 FROM tt_charges WHERE id=OLD.charge_id) BEGIN SELECT RAISE(ABORT,'Accounting history is never deleted'); END;
CREATE TRIGGER tt_adjustment_kept BEFORE DELETE ON tt_adjustments WHEN EXISTS(SELECT 1 FROM tt_charges WHERE id=OLD.charge_id) BEGIN SELECT RAISE(ABORT,'Accounting history is never deleted'); END;
