-- ACCT-001: immutable balanced USD entries, with beneficiary and fund held per entry.
CREATE TABLE tt_gl_accounts(code TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('asset','liability','income','expense','equity')),fund TEXT NOT NULL CHECK(fund IN ('operating','deposit','both')),cash INTEGER NOT NULL DEFAULT 0 CHECK(cash IN (0,1)),created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE VIEW tt_gl_chart AS SELECT column1 AS code,column2 AS name,column3 AS kind,column4 AS fund,column5 AS cash,column6 AS created_by,column7 AS created_at FROM (VALUES ('cash','Recorded external cash','asset','both',1,'migration','2026-10-22'),('receivable','Lease receivable','asset','operating',0,'migration','2026-10-22'),('lease_income','Lease income','income','operating',0,'migration','2026-10-22'),('deposit_liability','Resident security deposits','liability','deposit',0,'migration','2026-10-22'),('expense','Property expenses','expense','operating',0,'migration','2026-10-22'),('payable','Vendor payables','liability','operating',0,'migration','2026-10-22'),('fee_expense','Management expenses including recorded fee tax','expense','operating',0,'migration','2026-10-22'),('fee_payable','Management fee payables','liability','operating',0,'migration','2026-10-22'),('tax_payable','Lease tax payable','liability','operating',0,'migration','2026-10-22'),('contribution','Owner contributions','equity','operating',0,'migration','2026-10-22'),('opening_equity','Opening balance equity','equity','both',0,'migration','2026-10-22')) UNION ALL SELECT * FROM tt_gl_accounts;
CREATE TABLE tt_journal(id TEXT PRIMARY KEY,day TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'),property_id TEXT REFERENCES tt_properties(id),owner_key TEXT NOT NULL,tenancy_id TEXT REFERENCES tt_tenancies(id),vendor_id TEXT REFERENCES tt_vendors(id),fund TEXT NOT NULL CHECK(fund IN ('operating','deposit')),source_kind TEXT NOT NULL,source_id TEXT NOT NULL,reference TEXT NOT NULL,lines TEXT NOT NULL CHECK(json_valid(lines)),reversal_of TEXT UNIQUE REFERENCES tt_journal(id),recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(source_kind,source_id,owner_key));
CREATE VIEW tt_journal_lines AS SELECT j.*,CAST(l.key AS INTEGER) AS position,json_extract(l.value,'$.account') AS account,json_extract(l.value,'$.debit') AS debit_cents,json_extract(l.value,'$.credit') AS credit_cents FROM tt_journal j,json_each(j.lines) l;
CREATE INDEX tt_journal_owner ON tt_journal(owner_key,property_id,day);
CREATE INDEX tt_journal_tenancy ON tt_journal(tenancy_id,day);
CREATE TRIGGER tt_journal_balanced BEFORE INSERT ON tt_journal BEGIN
 SELECT CASE WHEN json_type(NEW.lines)<>'array' OR json_array_length(NEW.lines)<2 OR json_array_length(NEW.lines)>100 OR EXISTS(SELECT 1 FROM json_each(NEW.lines) l LEFT JOIN tt_gl_chart a ON a.code=json_extract(l.value,'$.account') WHERE a.code IS NULL OR (a.fund<>'both' AND a.fund<>NEW.fund) OR json_type(l.value,'$.debit') IS NOT 'integer' OR json_type(l.value,'$.credit') IS NOT 'integer' OR json_extract(l.value,'$.debit')<0 OR json_extract(l.value,'$.credit')<0 OR json_extract(l.value,'$.debit')>100000000 OR json_extract(l.value,'$.credit')>100000000 OR (json_extract(l.value,'$.debit')=0)=(json_extract(l.value,'$.credit')=0)) OR (SELECT SUM(json_extract(value,'$.debit')-json_extract(value,'$.credit')) FROM json_each(NEW.lines))<>0 THEN RAISE(ABORT,'unbalanced_journal') END;
 SELECT CASE WHEN NEW.reversal_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tt_journal o WHERE o.id=NEW.reversal_of AND o.reversal_of IS NULL AND o.property_id IS NEW.property_id AND o.owner_key=NEW.owner_key AND o.tenancy_id IS NEW.tenancy_id AND o.vendor_id IS NEW.vendor_id AND o.fund=NEW.fund AND NEW.lines=(SELECT json_group_array(json_object('account',json_extract(value,'$.account'),'debit',json_extract(value,'$.credit'),'credit',json_extract(value,'$.debit'))) FROM json_each(o.lines))) THEN RAISE(ABORT,'invalid_reversal') END;
 -- An entry is balanced within one owner/property/fund. Cash cannot be borrowed from any other bucket.
 SELECT CASE WHEN COALESCE((SELECT SUM(l.debit_cents-l.credit_cents) FROM tt_journal_lines l JOIN tt_gl_chart a ON a.code=l.account WHERE a.cash=1 AND l.property_id IS NEW.property_id AND l.owner_key=NEW.owner_key AND l.fund=NEW.fund),0)+(SELECT COALESCE(SUM(json_extract(l.value,'$.debit')-json_extract(l.value,'$.credit')),0) FROM json_each(NEW.lines) l JOIN tt_gl_chart a ON a.code=json_extract(l.value,'$.account') WHERE a.cash=1)<0 THEN RAISE(ABORT,'insufficient_owner_funds') END;
END;
CREATE TRIGGER tt_journal_kept BEFORE DELETE ON tt_journal BEGIN SELECT RAISE(ABORT,'Journal entries are never deleted'); END;
CREATE TRIGGER tt_journal_immutable BEFORE UPDATE ON tt_journal WHEN NOT (EXISTS(SELECT 1 FROM tt_erasure_work w WHERE w.tenancy_id=OLD.tenancy_id) AND NEW.reference=OLD.id AND NEW.id=OLD.id AND NEW.day=OLD.day AND NEW.currency=OLD.currency AND NEW.property_id IS OLD.property_id AND NEW.owner_key=OLD.owner_key AND NEW.tenancy_id IS OLD.tenancy_id AND NEW.vendor_id IS OLD.vendor_id AND NEW.fund=OLD.fund AND NEW.source_kind=OLD.source_kind AND NEW.source_id=OLD.source_id AND NEW.lines=OLD.lines AND NEW.reversal_of IS OLD.reversal_of AND NEW.recorded_by=OLD.recorded_by AND NEW.recorded_at=OLD.recorded_at) BEGIN SELECT RAISE(ABORT,'Journal entries are never edited'); END;
