-- Sources are projected once, inside the source transaction. Dated owner shares and exact cent allocation
-- are frozen in the resulting entry. Legacy unit-less records retain an opaque recorded-owner key.
CREATE VIEW tt_gl_sources AS
 SELECT q.id AS sid,'charge' AS kind,q.due_date AS day,u.property_id,t.id AS tenancy_id,NULL AS vendor_id,NULL AS owner_hint,q.amount_cents AS amount_cents,'receivable' AS debit,CASE WHEN q.tax_rule_id IS NULL THEN 'lease_income' ELSE 'tax_payable' END AS credit,q.reference,q.created_at AS at,q.currency FROM tt_charges q JOIN tt_tenancies t ON t.id=q.tenancy_id LEFT JOIN tt_units u ON u.id=t.unit_id
 UNION ALL SELECT r.id,'receipt',r.received_date,u.property_id,t.id,NULL,NULL,r.amount_cents,'cash','receivable',r.reference,r.created_at,r.currency FROM tt_receipts r JOIN tt_charges q ON q.id=r.charge_id JOIN tt_tenancies t ON t.id=q.tenancy_id LEFT JOIN tt_units u ON u.id=t.unit_id
 UNION ALL SELECT a.id,'reduction',COALESCE(a.posting_day,substr(a.at,1,10)),u.property_id,t.id,NULL,NULL,a.amount_cents,CASE WHEN q.tax_rule_id IS NULL THEN 'lease_income' ELSE 'tax_payable' END,'receivable',a.reason,a.at,a.currency FROM tt_adjustments a JOIN tt_charges q ON q.id=a.charge_id JOIN tt_tenancies t ON t.id=q.tenancy_id LEFT JOIN tt_units u ON u.id=t.unit_id
 UNION ALL SELECT x.id,'bill',x.day,x.property_id,NULL,COALESCE(json_extract(rev.terms,'$.vendorId'),b.vendor_id),x.owner_id,x.amount_cents,'expense','payable',b.id,b.created_at,'USD' FROM tt_bill_expenses x JOIN tt_bills b ON b.id=x.bill_id JOIN tt_bill_revisions rev ON rev.bill_id=x.bill_id AND rev.version=x.version
 UNION ALL SELECT f.id,'fee',f.day,f.property_id,NULL,NULL,f.owner_id,f.amount_cents+f.tax_cents,'fee_expense','fee_payable',f.id,f.created_at,'USD' FROM tt_fees f;
CREATE VIEW tt_gl_allocations AS
 SELECT s.*,COALESCE(s.owner_hint,h.owner_id,'lease-owner:'||s.tenancy_id) AS beneficiary,
 CASE WHEN h.owner_id IS NULL THEN s.amount_cents ELSE CAST(s.amount_cents*h.share_bp/10000 AS INTEGER)+CASE WHEN h.owner_id=(SELECT owner_id FROM tt_ownership_shares WHERE set_id=h.set_id ORDER BY share_bp DESC,position LIMIT 1) THEN s.amount_cents-(SELECT SUM(CAST(s.amount_cents*z.share_bp/10000 AS INTEGER)) FROM tt_ownership_shares z WHERE z.set_id=h.set_id) ELSE 0 END END AS allocated
 FROM tt_gl_sources s LEFT JOIN tt_ownership_shares h ON s.owner_hint IS NULL AND h.set_id=(SELECT id FROM tt_ownership_sets WHERE property_id=s.property_id AND effective_from<=s.day ORDER BY effective_from DESC LIMIT 1) WHERE s.currency='USD';
CREATE VIEW tt_gl_native AS SELECT 'native:'||kind||':'||sid||':'||beneficiary AS id,day,property_id,beneficiary AS owner_key,tenancy_id,vendor_id,'operating' AS fund,kind AS source_kind,sid AS source_id,reference,
 json_array(json_object('account',CASE WHEN allocated>0 THEN debit ELSE credit END,'debit',ABS(allocated),'credit',0),json_object('account',CASE WHEN allocated>0 THEN credit ELSE debit END,'debit',0,'credit',ABS(allocated))) AS lines,'native:'||kind AS recorded_by,at AS recorded_at FROM tt_gl_allocations WHERE allocated<>0;
INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at) SELECT * FROM tt_gl_native ORDER BY recorded_at,source_kind,id;
-- A pre-existing bill revision already superseded an earlier payable before this migration existed.
-- Retain both historical expenses and their inverse, leaving only the current payable outstanding.
INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,vendor_id,fund,source_kind,source_id,reference,lines,reversal_of,recorded_by,recorded_at)
 SELECT 'bill-revision:'||j.id,j.day,j.property_id,j.owner_key,j.tenancy_id,j.vendor_id,j.fund,'bill_reversal',j.id,j.id,(SELECT json_group_array(json_object('account',json_extract(value,'$.account'),'debit',json_extract(value,'$.credit'),'credit',json_extract(value,'$.debit'))) FROM json_each(j.lines)),j.id,'native:bill_revision',COALESCE((SELECT prepared_at FROM tt_bill_revisions WHERE bill_id=x.bill_id AND version=x.version+1),b.created_at) FROM tt_journal j JOIN tt_bill_expenses x ON x.id=j.source_id JOIN tt_bills b ON b.id=x.bill_id WHERE j.source_kind='bill' AND x.version<b.version;

