CREATE TRIGGER tt_chargeback_fixed BEFORE UPDATE ON tt_work_chargebacks WHEN NOT(NEW.id=OLD.id AND NEW.tenancy_id=OLD.tenancy_id AND NEW.source_id=OLD.source_id AND NEW.amount_cents=OLD.amount_cents AND NEW.day=OLD.day AND NEW.sha256=OLD.sha256 AND NEW.prepared_by=OLD.prepared_by AND NEW.prepared_at=OLD.prepared_at AND EXISTS(SELECT 1 FROM tt_erasure_work WHERE tenancy_id=OLD.tenancy_id)) BEGIN SELECT RAISE(ABORT,'Chargeback terms are immutable'); END;
