CREATE INDEX tt_hap_tenancy ON tt_hap_charges(tenancy_id,due_date);
CREATE TRIGGER tt_hap_charge_fixed BEFORE UPDATE ON tt_hap_charges WHEN NOT(EXISTS(SELECT 1 FROM tt_erasure_work WHERE tenancy_id=OLD.tenancy_id) AND NEW.payer='Retained housing authority' AND NEW.contract_reference=OLD.id AND NEW.source_clause='Retained accounting record' AND NEW.id=OLD.id AND NEW.tenancy_id=OLD.tenancy_id AND NEW.lease_version_id=OLD.lease_version_id AND NEW.term_id=OLD.term_id AND NEW.period_start=OLD.period_start AND NEW.period_end=OLD.period_end AND NEW.due_date=OLD.due_date AND NEW.amount_cents=OLD.amount_cents AND NEW.currency=OLD.currency AND NEW.reference=OLD.reference AND NEW.created_at=OLD.created_at) BEGIN SELECT RAISE(ABORT,'HAP charges are immutable'); END;
CREATE TRIGGER tt_hap_charge_kept BEFORE DELETE ON tt_hap_charges BEGIN SELECT RAISE(ABORT,'HAP charges are never deleted'); END;
CREATE VIEW tt_hap_gl_allocations AS
 SELECT q.*,u.property_id,COALESCE(h.owner_id,'lease-owner:'||t.id) AS beneficiary,
 CASE WHEN h.owner_id IS NULL THEN q.amount_cents ELSE CAST(q.amount_cents*h.share_bp/10000 AS INTEGER)+CASE WHEN h.owner_id=(SELECT owner_id FROM tt_ownership_shares WHERE set_id=h.set_id ORDER BY share_bp DESC,position LIMIT 1) THEN q.amount_cents-(SELECT SUM(CAST(q.amount_cents*z.share_bp/10000 AS INTEGER)) FROM tt_ownership_shares z WHERE z.set_id=h.set_id) ELSE 0 END END AS allocated
 FROM tt_hap_charges q JOIN tt_tenancies t ON t.id=q.tenancy_id LEFT JOIN tt_units u ON u.id=t.unit_id LEFT JOIN tt_ownership_shares h ON h.set_id=(SELECT id FROM tt_ownership_sets WHERE property_id=u.property_id AND effective_from<=q.due_date ORDER BY effective_from DESC LIMIT 1);
CREATE TRIGGER tt_hap_charge_journal AFTER INSERT ON tt_hap_charges BEGIN
 INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at)
 SELECT 'native:hap_charge:'||id||':'||beneficiary,due_date,property_id,beneficiary,tenancy_id,'operating','hap_charge',id,reference,json_array(json_object('account','receivable','debit',allocated,'credit',0),json_object('account','lease_income','debit',0,'credit',allocated)),'native:hap_charge',created_at FROM tt_hap_gl_allocations WHERE id=NEW.id AND allocated>0;
END;

